package ais.action.master.sosial;

import java.util.Arrays; import java.util.List; import javax.servlet.http.HttpServletRequest;
import org.hibernate.Criteria; import org.hibernate.Session; import org.hibernate.criterion.*; import org.zkoss.zk.ui.Component; import org.zkoss.zk.ui.Executions; import org.zkoss.zk.ui.Page; import org.zkoss.zk.ui.event.Event; import org.zkoss.zk.ui.event.EventListener; import org.zkoss.zk.ui.metainfo.ComponentInfo; import org.zkoss.zk.ui.util.GenericAutowireComposer; import org.zkoss.zul.*;
import ais.action.master.akunting.helper.AmbilDataAkunBanbox; import ais.action.master.sosial.helper.*; import ais.common.*; import ais.database.hibernate.HibernateUtil; import ais.database.model.GeneralValueObject; import ais.database.model.akunting.Akun; import ais.database.model.sekolah.*; import ais.database.model.sosial.*; import ais.ui.util.*;

/** CRUD ZKoss master SosialChannel, mengikuti pola KanalPembayaran AIS. */
public class SosialChannelAction extends GenericAutowireComposer implements DataCriteria,DataSearchDefault,DataInitDefault {
 private static final long serialVersionUID=1L; private MyWindow addWindow; private Paging paging; private MyGrid grid; private Textbox searchnama; private Checkbox searchaktif; private Label totalChannel,totalAktif,totalSmartlink; private MyToolbarbuttonConfig add; private boolean edit,delete; private SosialChannel entity; private SocialRequestContext context; private Textbox kode,nama,keterangan,url,username,password,channels,callbackSecret,allowedIps; private Combobox mode,yayasan,sekolah; private Checkbox aktif,smartlinkEnabled,useZakat,useInfaq,useShodaqoh,useDonasi; private Decimalbox fee; private AmbilDataAkunBanbox akun;
 public ComponentInfo doBeforeCompose(Page p,Component parent,ComponentInfo i){Common.doCheckSecurity();return super.doBeforeCompose(p,parent,i);}
 public void doAfterCompose(Component comp)throws Exception{super.doAfterCompose(comp);Common.initLaguage();context=SocialRequestContext.from((HttpServletRequest)Executions.getCurrent().getNativeRequest());new SocialPrivilegeGuard().require(context,SocialPrivilegeGuard.ADMIN);edit=CommonPrivilages.checkPrevilages(CommonPrivilages.UPDATE);delete=CommonPrivilages.checkPrevilages(CommonPrivilages.DELETE);add.setVisible(CommonPrivilages.checkPrevilages(CommonPrivilages.CREATE));Common.initPaging(paging,new EventListener(){public void onEvent(Event e)throws Exception{onSearchDefault(null);}});onSearchDefault(null);}
 public void onAdd(Event e)throws Exception{init(new SosialChannel());} public void init(GeneralValueObject v)throws Exception{entity=(SosialChannel)v;buildForm();callbackSecret.setTooltiptext(entity.getId()==null?"Minimal 32 karakter":"Kosongkan untuk mempertahankan secret");addWindow.setVisible(true);addWindow.onModal();}
 private void buildForm(){addWindow.setTitle(entity.getId()==null?"Tambah SosialChannel":"Ubah SosialChannel");Common.clear(addWindow);Grid form=new MyGrid();Rows rows=new Rows();rows.setParent(form);row(rows,"Kode",kode=new Textbox(entity.getKode()));row(rows,"Nama Channel",nama=new Textbox(entity.getNama()));row(rows,"Akun Kas/Bank",akun=new AmbilDataAkunBanbox());akun.setValue(entity.getAkun()==null?"":entity.getAkun().getNama());akun.setAttribute("akun",entity.getAkun());yayasan=new Combobox();sekolah=new Combobox();Common.initYayasanDanSekolahDanSemua(yayasan,sekolah,null,null);Common.selectComboItem(yayasan,entity.getYayasan());Common.pilihSekolah(sekolah,entity.getSekolah());row(rows,"Yayasan",yayasan);row(rows,"Sekolah",sekolah);row(rows,"Mode",mode=new Combobox());mode.setReadonly(true);mode.appendItem("Sandbox").setValue("SANDBOX");mode.appendItem("Production").setValue("PRODUCTION");select(mode,entity.getOperationMode());row(rows,"Status",aktif=new Checkbox("Aktif"));aktif.setChecked(entity.getAktif());section(rows,"Pemetaan Jenis Dana");Hbox uses=new Hbox();useZakat=new Checkbox("Zakat");useInfaq=new Checkbox("Infaq");useShodaqoh=new Checkbox("Shodaqoh");useDonasi=new Checkbox("Donasi");for(Checkbox cb:new Checkbox[]{useZakat,useInfaq,useShodaqoh,useDonasi})cb.setParent(uses);if(entity.getId()==null){useZakat.setChecked(true);useInfaq.setChecked(true);useShodaqoh.setChecked(true);useDonasi.setChecked(true);}else{useZakat.setChecked(mapped("ZAKAT"));useInfaq.setChecked(mapped("INFAQ"));useShodaqoh.setChecked(mapped("SHODAQOH"));useDonasi.setChecked(mapped("DONASI"));}row(rows,"Digunakan oleh",uses);section(rows,"E-Smartlink");row(rows,"",smartlinkEnabled=new Checkbox("Aktifkan Pembayaran via Smartlink"));smartlinkEnabled.setChecked(entity.getSmartlinkEnabled());row(rows,"Smartlink URL",url=new Textbox(entity.getSmartlinkUrl()));row(rows,"Smartlink Username",username=new Textbox(entity.getSmartlinkUsername()));row(rows,"Smartlink Password",password=new Textbox());password.setType("password");password.setTooltiptext(entity.getId()==null?"Wajib diisi":"Kosongkan untuk mempertahankan password");row(rows,"Channel Pembayaran",channels=new Textbox(entity.getSmartlinkChannels()));row(rows,"Biaya Admin",fee=new Decimalbox(entity.getSmartlinkFee()));row(rows,"Callback Secret",callbackSecret=new Textbox());callbackSecret.setType("password");callbackSecret.setTooltiptext(entity.getId()==null?"Minimal 16 karakter":"Kosongkan untuk mempertahankan secret");row(rows,"Callback Allowed IP",allowedIps=new Textbox(entity.getSmartlinkCallbackAllowedIps()));row(rows,"Keterangan",keterangan=new Textbox(entity.getKeterangan()));keterangan.setRows(3);for(Component c:Arrays.asList(kode,nama,akun,yayasan,sekolah,mode,url,username,password,channels,fee,callbackSecret,allowedIps,keterangan))((org.zkoss.zk.ui.HtmlBasedComponent)c).setWidth("95%");Toolbar bar=new Toolbar();MyToolbarbuttonConfig cancel=new MyToolbarbuttonConfig("Batal","/img/cancel.gif"),save=new MyToolbarbuttonConfig("Simpan","/img/save.gif");cancel.addEventListener("onClick",new EventListener(){public void onEvent(Event e){addWindow.setVisible(false);}});save.addEventListener("onClick",new EventListener(){public void onEvent(Event e)throws Exception{if(onSave(e)){addWindow.setVisible(false);onSearchDefault(null);}}});cancel.setParent(bar);save.setParent(bar);Vbox box=new Vbox();box.setWidth("100%");form.setWidth("100%");form.setParent(box);bar.setParent(box);box.setParent(addWindow);}
 private void row(Rows rows,String text,Component field){Row r=new MyFormRow();r.appendChild(new MyLabelConfig(text+(text.length()>0?" *":"")));r.appendChild(field);r.setParent(rows);} private void section(Rows rows,String text){Row r=new MyFormRow();ZkCompat.setSpans(r,"2");r.appendChild(new MyLabelStyled(text));r.setParent(rows);} private void select(Combobox c,String value){for(Object o:c.getItems()){Comboitem i=(Comboitem)o;if(value!=null&&value.equals(i.getValue())){c.setSelectedItem(i);return;}}c.setSelectedIndex(0);}
 public boolean onSave(Event e)throws Exception{Akun a=(Akun)akun.getAttribute("akun");if(a==null){MyMessageboxConfig.show("Akun Kas/Bank wajib diisi.","Peringatan",MyMessageboxConfig.OK,MyMessageboxConfig.INFORMATION);return false;}Yayasan y=yayasan.getSelectedItem()==null?null:(Yayasan)yayasan.getSelectedItem().getValue();Sekolah sk=sekolah.getSelectedItem()==null?null:(Sekolah)sekolah.getSelectedItem().getValue();String m=mode.getSelectedItem()==null?"SANDBOX":String.valueOf(mode.getSelectedItem().getValue());SosialChannel saved=new SosialChannelAdminService().save(context,entity.getId(),kode.getValue().trim(),nama.getValue().trim(),keterangan.getValue(),a.getId(),y==null?null:y.getId(),sk==null?null:sk.getId(),aktif.isChecked(),smartlinkEnabled.isChecked(),m,url.getValue(),username.getValue(),password.getValue(),channels.getValue(),fee.getValue(),callbackSecret.getValue(),allowedIps.getValue());if(useZakat.isChecked())mapFund(saved,"ZAKAT","Zakat",true);if(useInfaq.isChecked())mapFund(saved,"INFAQ","Infaq",false);if(useShodaqoh.isChecked())mapFund(saved,"SHODAQOH","Shodaqoh",false);if(useDonasi.isChecked())mapFund(saved,"DONASI","Donasi",false);return true;}
 public Criteria initCriteria(boolean order){Criteria c=HibernateUtil.currentSession().createCriteria(SosialChannel.class).add(Restrictions.eq("tenantKey",context.getTenantKey())).add(empty(searchnama.getValue())?Restrictions.sqlRestriction("1=1"):Restrictions.ilike("nama",searchnama.getValue().trim(),MatchMode.ANYWHERE));if(searchaktif.isChecked())c.add(Restrictions.eq("aktif",Boolean.TRUE));if(order)c.addOrder(Order.asc("nama"));return c;}
 @SuppressWarnings("unchecked") public void onSearchDefault(Event e){Common.initPaging(initCriteria(false),paging);List<SosialChannel> list=initCriteria(true).setMaxResults(Common.ROWS_COUNT_ON_PAGE).setFirstResult(Common.ROWS_COUNT_ON_PAGE*(paging==null?0:paging.getActivePage())).list();grid.setRowRenderer(new MyRowRenderer(){public void render(Row r,Object o)throws Exception{SosialChannel c=(SosialChannel)o;new Label(c.getKode()).setParent(r);new Label(c.getNama()).setParent(r);new Label(c.getAkun()==null?"":c.getAkun().getNama()).setParent(r);new Label(c.getOperationMode()).setParent(r);new Label(c.getSmartlinkEnabled()?"Aktif":"Nonaktif").setParent(r);Checkbox ac=new Checkbox();ac.setChecked(c.getAktif());ac.setDisabled(true);ac.setParent(r);Common.copyEditDeleteButtons(edit,delete,c,SosialChannelAction.this).setParent(r);}});grid.setModelCheckMobile(new SimpleListModel(list));refreshDashboard();}
 private boolean mapped(String code){Number n=(Number)HibernateUtil.currentSession().createCriteria(JenisDanaSosial.class).createAlias("sosialChannel","c").add(Restrictions.eq("tenantKey",context.getTenantKey())).add(Restrictions.eq("kode",code)).add(Restrictions.eq("c.id",entity.getId())).setProjection(Projections.rowCount()).uniqueResult();return n!=null&&n.longValue()>0;}
 private void mapFund(SosialChannel saved,String code,String name,boolean restricted){Session s=HibernateUtil.currentSession();JenisDanaSosial f=(JenisDanaSosial)s.createCriteria(JenisDanaSosial.class).add(Restrictions.eq("tenantKey",context.getTenantKey())).add(Restrictions.eq("kode",code)).setMaxResults(1).uniqueResult();if(f==null){f=new JenisDanaSosial();f.setTenantKey(context.getTenantKey());f.setKode(code);f.setNama(name);f.setRestricted(Boolean.valueOf(restricted));f.setCalculationRequired(Boolean.valueOf("ZAKAT".equals(code)));f.setPublicActive(Boolean.TRUE);f.setReceiptType(code);f.setStatus("ACTIVE");f.setCreatedBy(context.getActorId());}f.setSosialChannel((SosialChannel)s.get(SosialChannel.class,saved.getId()));f.setUpdatedBy(context.getActorId());Common.refreshSaveOrUpdate(s,f);}
 private void refreshDashboard(){Session s=HibernateUtil.currentSession();totalChannel.setValue(String.valueOf(count(s,null,null)));totalAktif.setValue(String.valueOf(count(s,"aktif",Boolean.TRUE)));totalSmartlink.setValue(String.valueOf(count(s,"smartlinkEnabled",Boolean.TRUE)));} private long count(Session s,String field,Boolean value){Criteria c=s.createCriteria(SosialChannel.class).add(Restrictions.eq("tenantKey",context.getTenantKey()));if(field!=null)c.add(Restrictions.eq(field,value));Number n=(Number)c.setProjection(Projections.rowCount()).uniqueResult();return n==null?0:n.longValue();} private boolean empty(String v){return v==null||v.trim().isEmpty();}
}
